def solve(payload):
    x, y = payload["x_m"], payload["y"]
    h0, h1 = x[1]-x[0], x[2]-x[1]
    if h0 <= 0 or h1 <= 0:
        return {"error": "x_order"}
    s0, s1 = (y[1]-y[0])/h0, (y[2]-y[1])/h1
    return {"first_per_m": (h1*s0+h0*s1)/(h0+h1), "second_per_m2": 2*(s1-s0)/(h0+h1)}

